import{_ as r,C as n,o as s,c as e,j as t,E as d,a as l,a2 as o}from"./chunks/framework.C21TwvGF.js";const x=JSON.parse(`{"title":"4-hafta (Mentor)","description":"","frontmatter":{"title":"4-hafta (Mentor)","layout":"doc","sidebar":false,"aside":false,"outline":false,"kind":"mentor_hafta","hafta":{"sinf":{"name":"9-sinf (BI)","link":"/mentor/9-sinf-bi/"},"n":4,"bob":"II-bob · SQL va relatsion ma’lumotlar tahlili","lessons":[{"g":10,"title":"Relatsion ma'lumotlar bazalari va model tushunchasi (2-qism): Normalizatsiya asoslari va BI'dagi o'rni","lead":"Bitta katta Excel jadval — qulaydek tuyuladi. Lekin mijoz telefonini 50 joyda almashtirish kerak bo'lsa-chi? Bugun ma'lumotni «to'g'ri bo'laklarga ajratish» san'ati — normalizatsiyani o'rganamiz.","link":"/mentor/9-sinf-bi/hafta-04/dars-1","slide":"/slaydlar/9-sinf-bi/hafta-04/dars-1.html","test":"/slaydlar/9-sinf-bi/hafta-04/dars-1-test.html"},{"g":11,"title":"Relatsion ma'lumotlar bazalari va model tushunchasi (3-qism): RDBMS muhitlari va ma'lumotlar yaxlitligi","lead":"Excel'da manfiy narx yoki ikki xil bir xil ID ni hech kim to'xtatmaydi. Haqiqiy ma'lumotlar bazasi esa bunday xatoni «yo'q!» deb rad etadi. Bugun bazani himoya qiluvchi qoidalar — cheklovlar bilan tanishamiz.","link":"/mentor/9-sinf-bi/hafta-04/dars-2","slide":"/slaydlar/9-sinf-bi/hafta-04/dars-2.html","test":"/slaydlar/9-sinf-bi/hafta-04/dars-2-test.html"},{"g":12,"title":"SQL asoslari: SELECT, ustunlar va sodda ifodalar","lead":"Minglab qatorli jadvaldan kerakli ma'lumotni bir qator kod bilan olish — BI analitigining super kuchi. Bugun SQL ning eng muhim so'zi — SELECT bilan ishlaymiz.","link":"/mentor/9-sinf-bi/hafta-04/dars-3","slide":"/slaydlar/9-sinf-bi/hafta-04/dars-3.html","test":"/slaydlar/9-sinf-bi/hafta-04/dars-3-test.html"}],"test":"/slaydlar/9-sinf-bi/hafta-04/hafta-test.html"}},"headers":[],"relativePath":"mentor/9-sinf-bi/hafta-04/index.md","filePath":"mentor/9-sinf-bi/hafta-04/index.md"}`),h={name:"mentor/9-sinf-bi/hafta-04/index.md"},u={class:"blk"},c={id:"uyga-vazifa-va-mentor-tavsiyalari",tabindex:"-1"},m={class:"blk"},g={id:"baholash-mezoni",tabindex:"-1"};function b(v,a,y,f,k,q){const i=n("Icon");return s(),e("div",null,[t("div",u,[t("h2",c,[d(i,{name:"house"}),a[0]||(a[0]=l(" Uyga vazifa va mentor tavsiyalari ",-1)),a[1]||(a[1]=t("a",{class:"header-anchor",href:"#uyga-vazifa-va-mentor-tavsiyalari","aria-label":'Permalink to "<Icon name="house" /> Uyga vazifa va mentor tavsiyalari"'},"​",-1))]),a[2]||(a[2]=o('<p>Mazkur haftada o&#39;tilgan darslar bo&#39;yicha mustaqil bajarish uchun topshiriqlar. Har bir vazifa 20–30 daqiqaga mo&#39;ljallangan.</p><hr><h2 id="_10-dars-normalizatsiya-asoslari-va-bi-dagi-o-rni" tabindex="-1">10-dars: Normalizatsiya asoslari va BI&#39;dagi o&#39;rni <a class="header-anchor" href="#_10-dars-normalizatsiya-asoslari-va-bi-dagi-o-rni" aria-label="Permalink to &quot;10-dars: Normalizatsiya asoslari va BI&#39;dagi o&#39;rni&quot;">​</a></h2><ol><li>Quyidagi «yassi» kutubxona jadvalini oling: <code>KitobID, KitobNomi, Muallif, MuallifDavlati, OquvchiIsmi, OquvchiSinfi, OlinganSana, QaytarishSana</code>.</li><li>Undagi takrorlanuvchi ma&#39;lumotlarni belgilang va har bir anomaliya (Update, Insert, Delete) uchun bittadan misol yozing.</li><li>Jadvalni bosqichma-bosqich 1NF → 2NF → 3NF ga keltiring. Natijada 3–4 ta jadval hosil bo&#39;ladi (masalan: <code>Mualliflar</code>, <code>Kitoblar</code>, <code>Oquvchilar</code>, <code>Ijaralar</code>).</li><li>Sxemani daftarda chizing: har bir jadvalda PK, FK va munosabat turi (1:N, M:N) ko&#39;rsatilsin.</li></ol><p><strong>Kutiladigan natija:</strong> anomaliyalar tahlili va 3NF dagi bog&#39;langan jadvallar sxemasi.</p><hr><h2 id="_11-dars-rdbms-muhitlari-va-ma-lumotlar-yaxlitligi" tabindex="-1">11-dars: RDBMS muhitlari va ma&#39;lumotlar yaxlitligi <a class="header-anchor" href="#_11-dars-rdbms-muhitlari-va-ma-lumotlar-yaxlitligi" aria-label="Permalink to &quot;11-dars: RDBMS muhitlari va ma&#39;lumotlar yaxlitligi&quot;">​</a></h2><ol><li>10-dars uyga vazifasidagi kutubxona modeli uchun SSMS da (yoki SQLite da) <code>Kutubxona</code> bazasini yarating.</li><li>Har bir jadval uchun <code>CREATE TABLE</code> skriptini yozing: PK, kerakli FK, kamida bittadan <code>NOT NULL</code>, <code>UNIQUE</code>, <code>CHECK</code> (masalan, <code>QaytarishSana &gt;= OlinganSana</code>) va <code>DEFAULT</code>.</li><li>Har bir jadvalga 3 tadan to&#39;g&#39;ri yozuv qo&#39;shing (<code>INSERT</code>).</li><li>Har bir cheklov turini buzadigan bittadan <code>INSERT</code> yozing, bajaring va chiqqan xato xabarini 1 jumlada izohlang.</li></ol><p><strong>Kutiladigan natija:</strong> ishlaydigan skript, to&#39;ldirilgan jadvallar va 5 ta izohlangan xato.</p><hr><h2 id="_12-dars-sql-asoslari-—-select-ustunlar-va-sodda-ifodalar" tabindex="-1">12-dars: SQL asoslari — SELECT, ustunlar va sodda ifodalar <a class="header-anchor" href="#_12-dars-sql-asoslari-—-select-ustunlar-va-sodda-ifodalar" aria-label="Permalink to &quot;12-dars: SQL asoslari — SELECT, ustunlar va sodda ifodalar&quot;">​</a></h2><ol><li>Darsdagi <code>Mahsulotlar</code> jadvalini 10 ta mahsulotgacha to&#39;ldiring (yangi <code>INSERT</code> lar).</li><li>Quyidagi 6 ta so&#39;rovni yozing va bajaring: <ul><li>barcha ustunlar;</li><li>nomi va narxi <code>Mahsulot</code> va <code>Narx (so&#39;m)</code> taxalluslari bilan;</li><li>har bir mahsulotning ombor qiymati (<code>Narx * Soni</code>);</li><li>QQS bilan narx (<code>Narx * 1.12</code>);</li><li>takrorsiz kategoriyalar (<code>DISTINCT</code>);</li><li>birinchi 3 ta mahsulot (<code>TOP 3</code>).</li></ul></li><li>Har bir so&#39;rov ostiga natijada nechta qator va ustun chiqqanini hamda 1 ta xulosani yozing.</li></ol><p><strong>Kutiladigan natija:</strong> <code>.sql</code> fayl (yoki daftar) — 6 ta to&#39;g&#39;ri so&#39;rov va natijalar tavsifi.</p><hr><h2 id="mentor-uchun" tabindex="-1">Mentor uchun <a class="header-anchor" href="#mentor-uchun" aria-label="Permalink to &quot;Mentor uchun&quot;">​</a></h2><p>Keyingi dars boshida (13-dars, WHERE) 2–3 o&#39;quvchining 11-darsdagi xato xabarlarini ekranda ko&#39;rsatib muhokama qiling: qaysi cheklov qaysi yaxlitlik turini himoya qiladi. 12-darsdagi <code>Mahsulotlar</code> jadvali 13-darsda WHERE filtrlari uchun asos bo&#39;lib xizmat qiladi — o&#39;quvchilar uni saqlab qo&#39;ysin.</p>',16))]),t("div",m,[t("h2",g,[d(i,{name:"list-checks"}),a[3]||(a[3]=l(" Baholash mezoni ",-1)),a[4]||(a[4]=t("a",{class:"header-anchor",href:"#baholash-mezoni","aria-label":'Permalink to "<Icon name="list-checks" /> Baholash mezoni"'},"​",-1))]),a[5]||(a[5]=o('<p><strong>Mavzular:</strong></p><ol><li>Relatsion ma&#39;lumotlar bazalari va model tushunchasi (2-qism): Normalizatsiya asoslari va BI&#39;dagi o&#39;rni</li><li>Relatsion ma&#39;lumotlar bazalari va model tushunchasi (3-qism): RDBMS muhitlari va ma&#39;lumotlar yaxlitligi</li><li>SQL asoslari: SELECT, ustunlar va sodda ifodalar</li></ol><hr><h2 id="baholash-mezonlari" tabindex="-1">Baholash mezonlari <a class="header-anchor" href="#baholash-mezonlari" aria-label="Permalink to &quot;Baholash mezonlari&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Mezon</th><th>Tavsif</th><th>Maks. ball</th></tr></thead><tbody><tr><td><strong>Normalizatsiya</strong></td><td>Redundansiya va 3 anomaliyani aniqlash, jadvalni 1NF → 2NF → 3NF ga keltirish, Fact va Dimension jadvallarni ajratish</td><td>35 ball</td></tr><tr><td><strong>RDBMS va yaxlitlik</strong></td><td>RDBMS larni farqlash, SSMS da baza va jadval yaratish, PK, FK, NOT NULL, UNIQUE, CHECK, DEFAULT cheklovlarini to&#39;g&#39;ri qo&#39;llash, xato xabarini izohlash</td><td>30 ball</td></tr><tr><td><strong>SQL SELECT</strong></td><td>Buyruq toifalari, <code>SELECT *</code> va ustunli so&#39;rov, <code>AS</code>, hisoblangan ustunlar, <code>DISTINCT</code>, <code>TOP</code>, natijani bashorat qilish</td><td>35 ball</td></tr><tr><td><strong>JAMI</strong></td><td></td><td><strong>100 ball</strong></td></tr></tbody></table><p>Dasturdagi shkala: <strong>90–100 — 5</strong>, <strong>71–89 — 4</strong>, <strong>60–70 — 3</strong>, <strong>0–59 — 2</strong>.</p><hr><h2 id="o-quvchilar-natijalari-jadvali" tabindex="-1">O&#39;quvchilar natijalari jadvali <a class="header-anchor" href="#o-quvchilar-natijalari-jadvali" aria-label="Permalink to &quot;O&#39;quvchilar natijalari jadvali&quot;">​</a></h2><table tabindex="0"><thead><tr><th>№</th><th>O&#39;quvchi F.I.Sh.</th><th>Normalizatsiya (35)</th><th>RDBMS va yaxlitlik (30)</th><th>SQL SELECT (35)</th><th>Jami ball (100)</th><th>Izoh</th></tr></thead><tbody><tr><td>1</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>2</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>3</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>4</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>5</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>6</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>7</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>8</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>9</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>10</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>11</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>12</td><td></td><td></td><td></td><td></td><td></td><td></td></tr></tbody></table><hr><h2 id="mentor-qaydlari-va-tahlil" tabindex="-1">Mentor qaydlari va tahlil <a class="header-anchor" href="#mentor-qaydlari-va-tahlil" aria-label="Permalink to &quot;Mentor qaydlari va tahlil&quot;">​</a></h2><ul><li><strong>Darsdagi asosiy qiyinchiliklar:</strong> O&#39;quvchilar 2NF va 3NF ni chalkashtiradi: 2NF — kompozit kalitning <strong>bir qismiga</strong> bog&#39;liqlik, 3NF — kalit bo&#39;lmagan <strong>boshqa ustunga</strong> bog&#39;liqlik ekanini «kalitga, butun kalitga, faqat kalitga» qoidasi bilan mustahkamlang. SQL da eng ko&#39;p uchraydigan xatolar: ustunlar orasida vergulni unutish, <code>FROM</code> o&#39;rniga <code>FORM</code>, o&#39;zbekcha matnda apostrofni ikkilantirmaslik (<code>N&#39;O&#39;&#39;g&#39;&#39;il&#39;</code>), hisoblangan ustunga <code>AS</code> bermaslik.</li><li><strong>Iqtidorli o&#39;quvchilar uchun:</strong> 4–5 jadvalli do&#39;kon modelini to&#39;liq cheklovlar bilan yaratish va undan Star schema (1 Fact + 3 Dimension) loyihalash; <code>SELECT</code> da <code>CONCAT</code>, <code>ROUND</code>, <code>CAST</code> funksiyalarini mustaqil o&#39;rganish.</li><li><strong>Keyingi haftaga ko&#39;prik:</strong> 13-darsda <code>WHERE</code>, taqqoslash va mantiqiy operatorlar (<code>AND</code>, <code>OR</code>, <code>NOT</code>) o&#39;rganiladi — 12-darsdagi <code>Mahsulotlar</code> jadvali shu darsda filtrlash uchun ishlatiladi.</li></ul>',12))])])}const z=r(h,[["render",b]]);export{x as __pageData,z as default};
